  for (let y=0;y<7;y++) for (let dx=0;dx<2;dx++) for (let dz=0;dz<2;dz++) addVoxel(cx+dx,y,cz+dz,'#5b3a22');
  // branches
  const branch=[[1,6,0],[0,6,1],[-1,5,0],[0,5,-1],[1,5,1]];
  for (const [dx,dy,dz] of branch) {
    for (let i=0;i<3;i++) addVoxel(cx+dx+i, dy, cz+dz, '#5b3a22');
  }
  // blossoms clusters
  const center={x:cx+0.5,y:7.5,z:cz+0.5};
  let seed=12345;
  function rnd(){ seed=(seed*9301+49297)%233280; return seed/233280; }
  for (let i=0;i<260;i++){
    const u=rnd()*2-1; const v=rnd()*2-1; const w=rnd()*2-1;
    if (u*u+v*v+w*w>1) continue;
    const x=Math.round(center.x+u*3.2);
    const y=Math.round(center.y+v*2.6);
    const z=Math.round(center.z+w*3.2);
    if (y<5) continue;
    const c = rnd()>0.5 ? '#ff9ec9' : '#ffc0dd';
    addVoxel(x,y,z,c);
  }
}

